// Lógica para tratar mensagens mencionadas no N8N
// Com suporte a áudio mencionado

// ADIÇÃO: Verifica se a mensagem vem do OpenAI3 (áudio transcrito)
// Usa verificação de entrada para detectar se vem do OpenAI3
let mensagemVemDoOpenAI3 = false;
let transcricaoTexto = "";

// Verifica se existe uma entrada que não seja do Webhook EVO
const entradas = Object.keys($input.all());
if (entradas.length > 1) {
  // Se tem mais de uma entrada, verifica se uma delas tem texto transcrito
  for (let entrada of entradas) {
    if (entrada !== 'Webhook EVO') {
      const dadosEntrada = $input.all()[entrada];
      if (dadosEntrada && dadosEntrada[0] && dadosEntrada[0].json && dadosEntrada[0].json.text) {
        mensagemVemDoOpenAI3 = true;
        transcricaoTexto = dadosEntrada[0].json.text;
        break;
      }
    }
  }
}

// SEU CÓDIGO ORIGINAL (sem modificações):
// Extrai a mensagem atual
let mensagemAtual = "";

// Se vem do OpenAI3 (áudio transcrito), usa a transcrição
if (mensagemVemDoOpenAI3) {
  mensagemAtual = transcricaoTexto;
} else {
  // Senão, usa a mensagem normal do webhook
  mensagemAtual = $('Webhook EVO').first().json.body.data.message.conversation || "";
}

// Inicializa variáveis para menção
let mensagemMencionada = "";
let audioMencionadoId = null;
let tipoMencao = "texto"; // pode ser: "texto", "audio"

// Verifica se tem mensagem mencionada
if ($('Webhook EVO').first().json.body.data.contextInfo && $('Webhook EVO').first().json.body.data.contextInfo.quotedMessage) {

  const quotedMessage = $('Webhook EVO').first().json.body.data.contextInfo.quotedMessage;

  // Verifica se é texto
  if (quotedMessage.conversation) {
    mensagemMencionada = quotedMessage.conversation;
    tipoMencao = "texto";
  }
  // Verifica se é áudio
  else if (quotedMessage.audioMessage) {
    // Captura o ID do áudio (stanzaId) para buscar o base64
    audioMencionadoId = $('Webhook EVO').first().json.body.data.contextInfo.stanzaId;
    mensagemMencionada = "[ÁUDIO MENCIONADO]";
    tipoMencao = "audio";
  }
  // Outros tipos de mídia (opcional)
  else if (quotedMessage.imageMessage) {
    mensagemMencionada = "[IMAGEM MENCIONADA]";
    tipoMencao = "imagem";
  }
  else if (quotedMessage.videoMessage) {
    mensagemMencionada = "[VÍDEO MENCIONADO]";
    tipoMencao = "video";
  }
  else if (quotedMessage.documentMessage) {
    mensagemMencionada = "[DOCUMENTO MENCIONADO]";
    tipoMencao = "documento";
  }
}

// Variável para a mensagem final
let mensagemFinal = mensagemAtual;

// Se existe menção, junta as mensagens
if (mensagemMencionada) {
  if (tipoMencao === "audio") {
    mensagemFinal = `ÁUDIO MENCIONADO (ID: ${audioMencionadoId})

Referenciando a anterior: "${mensagemAtual}"

INSTRUÇÃO: O cliente está respondendo a um áudio anterior. Você precisa transcrever o áudio usando o ID fornecido antes de responder.`;
  } else {
    mensagemFinal = `Mensagem anterior: "${mensagemMencionada}"

Referenciando a anterior: "${mensagemAtual}"

Responda considerando que a segunda mensagem se refere à primeira.`;
  }
}

// Retorna o resultado
return {
  mensagemTratada: mensagemFinal,
  temMencao: mensagemMencionada ? true : false,
  tipoMencao: tipoMencao,
  mensagemOriginal: mensagemAtual,
  mensagemMencionada: mensagemMencionada,
  audioMencionadoId: audioMencionadoId,
  // Para usar no próximo nó se for áudio
  precisaTranscrever: tipoMencao === "audio"
};

// Pegar os records do input
const messages = $('BUSCA CONVERSA1').first().json.messages.records;

// Processar mensagens de forma simplificada
const processedMessages = messages.map(msg => {
  // Extrair conteúdo baseado no tipo
  let content = '';

  switch(msg.messageType) {
    case 'conversation':
      content = msg.message.conversation;
      break;
    case 'audioMessage':
      // Para áudio, usar o ID dentro de key
      content = msg.key.id;
      break;
    case 'documentMessage':
      content = `[Documento: ${msg.message.documentMessage?.fileName || 'arquivo'}]`;
      break;
    case 'imageMessage':
      content = `[Imagem${msg.message.imageMessage?.caption ? ': ' + msg.message.imageMessage.caption : ''}]`;
      break;
    case 'videoMessage':
      content = `[Vídeo${msg.message.videoMessage?.caption ? ': ' + msg.message.videoMessage.caption : ''}]`;
      break;
    default:
      content = '[Mensagem]';
  }

  // Retornar objeto simplificado
  return {
    message: content,
    fromMe: msg.key.fromMe,
    timestamp: msg.messageTimestamp,
    type: msg.key.fromMe ? 'assistant' : 'lead',
    isAudio: msg.messageType === 'audioMessage'
  };
});

// Ordenar por timestamp (mais antigas primeiro)
processedMessages.sort((a, b) => a.timestamp - b.timestamp);

// Retornar no formato esperado pelo n8n
return processedMessages.map(msg => ({
  json: {
    message: msg.message,
    fromMe: msg.fromMe,
    type: msg.type,
    isAudio: msg.isAudio
  }
}));

// Pegar todos os itens do node anterior
const items = $input.all();

// Filtrar apenas os áudios
const audioMessages = items.filter(item => item.json.isAudio === true);

// Se não houver áudios, retornar um item vazio para o IF processar
if (audioMessages.length === 0) {
  return [{
    json: {
      hasAudio: false,
      message: "Sem áudios para processar"
    }
  }];
}

// Retornar CADA ÁUDIO como um item separado
return audioMessages.map(audio => ({
  json: {
    audioId: audio.json.message,  // ID do áudio no Evolution
    fromMe: audio.json.fromMe,
    type: audio.json.type,
    isAudio: true
  }
}));

// Versão simplificada - assumindo que temos 2 inputs
const messages = $items("Code7");
const transcriptions = $input.all("OpenAI");

let transcriptionIndex = 0;

return messages.map(msg => {
  if (msg.json.isAudio === true && transcriptionIndex < transcriptions.length) {
    const text = transcriptions[transcriptionIndex].json.text;
    transcriptionIndex++;

    return {
      json: {
        message: text,
        fromMe: msg.json.fromMe,
        type: msg.json.type,
        wasAudio: true
      }
    };
  }

  return {
    json: msg.json
  };
});

// Código para juntar áudio transcrito com mensagem atual
// Usado após a transcrição do áudio mencionado

// Pega a transcrição do áudio do nó anterior (OpenAI2)
let transcricaoAudio = $('OpenAI2').first().json.text || "";

// Pega os dados do nó de tratamento inicial (Code6)
let dadosTratamento = $('Code6').first().json;

// Pega a mensagem atual do cliente
let mensagemAtual = dadosTratamento.mensagemOriginal || "";

// Monta a mensagem final de forma mais concisa
let mensagemFinalComAudio = `Mensagem anterior mencionada: "${transcricaoAudio}"

Referenciando a anterior: "${mensagemAtual}"

Responda considerando que a segunda mensagem se refere à primeira.`;

// Retorna o resultado final
return {
  mensagemTratada: mensagemFinalComAudio,
  transcricaoAudio: transcricaoAudio,
  mensagemOriginal: mensagemAtual,
  temMencao: true,
  tipoMencao: "audio_transcrito"
};

// Pegar todos os items do Code6
const allMessages = $('Code9').all();

// Formatar cada mensagem para adicionar na thread
const formattedMessages = allMessages.map((item, index) => {
  // Extrair dados da mensagem
  const message = item.json.message;
  const type = item.json.type; // 'user' ou 'assistant'
  const fromMe = item.json.fromMe;

  // Determinar o role correto
  // Se type existe, usar ele. Senão, basear em fromMe
  let role = type || (fromMe ? 'assistant' : 'user');
  if (role === 'lead') {
    role = 'user';
  }

  return {
    json: {
      // Dados para adicionar na thread
      role: role,
      content: message,

      // Metadados adicionais
      messageIndex: index,
      isUser: role === 'user',
      isAssistant: role === 'assistant',
      fromMe: fromMe,

      // Dados para controle
      totalMessages: allMessages.length,
      isLastMessage: index === allMessages.length - 1,
      isFirstMessage: index === 0
    }
  };
});

// Retornar cada mensagem como um item separado
return formattedMessages;
